async function enter(){if(busy||blocked)return;const nickname=$('nickname').value.trim();if(!nickname){$('entryError').textContent='先取一个喜欢的学习昵称吧。';return;}busy=true;try{const profiles=readProfiles();let person=profiles.find(p=>p.nickname===nickname);if(!person){person={id:E.uid(),nickname,createdAt:new Date().toISOString()};profiles.push(person);localStorage.setItem(USERS,JSON.stringify(profiles));}localStorage.setItem(ACTIVE,JSON.stringify({id:person.id,grade,term}));who=person;load();$('entry').hidden=true;$('app').hidden=false;$('entryError').textContent='';renderDashboard();}catch(e){$('entryError').textContent='无法保存学习身份：'+e.message;}finally{busy=false;}}
