function openModal(title,eyebrow,html,mode){cleanup();modalMode=mode;modalEpoch++;lastFocus=document.activeElement;$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;hydrate($('modal'));$('modal').hidden=false;document.body.style.overflow='hidden';document.querySelector('.dialog').scrollTop=0;document.querySelector('.dialog').focus();}
