function chime(){if(!state?.effects)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;ctx=ctx||new AC();const play=()=>[659.25,830.61,987.77].forEach((f,i)=>{const t=ctx.currentTime+.02+i*.1,o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.16,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.25);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.27);});if(ctx.state==='suspended')ctx.resume().then(play).catch(()=>{});else play();}catch{}}
function speak(text,rate=.8,onDone){if(captureSession){toast('请先结束录音，再听伙伴的声音。');return;}const token=++audioToken;if(narration){narration.pause();narration=null;}window.speechSynthesis?.cancel();const local=window.UnitAudio?.[text];if(local){const player=new Audio(local);narration=player;player.playbackRate=Math.max(.65,Math.min(1.15,rate/.8));player.preservesPitch=true;player.onended=()=>{if(token===audioToken){narration=null;onDone?.();}};player.onerror=()=>{if(token===audioToken)toast('配套音频暂未加载，请检查连接后重试，不会记为答错。');};player.play().catch(()=>{if(token===audioToken)toast('点一下播放按钮，或检查浏览器声音权限后重试。');});return;}if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){toast('此浏览器没有可用的英语朗读。此问题不会算作答错。');return;}const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;const voices=speechSynthesis.getVoices(),v=voices.find(v=>/^en[-_]/i.test(v.lang)&&/samantha|natural|google|aria/i.test(v.name))||voices.find(v=>/^en[-_]/i.test(v.lang));if(v)u.voice=v;u.onend=()=>{if(token===audioToken)onDone?.();};u.onerror=e=>{if(token===audioToken&&!['canceled','interrupted'].includes(e.error))toast('朗读暂未成功。请检查设备声音或换个浏览器重试，不会记为答错。');};speechSynthesis.speak(u);}
