const options=q.options?'<div class="choices '+(q.pictureOptions?'picture-choices':'')+'" id="choices">'+q.options.map((option,i)=>'<button class="choice" data-index="'+i+'" aria-pressed="'+String(option===chosen)+'"><span class="letter">'+String.fromCharCode(65+i)+'</span>'+(q.pictureOptions?A.picture(option):'')+'<span>'+esc(option)+'</span></button>').join('')+'</div>':'<label class="fine" for="taskAnswer">在这里写下你的回答</label><input class="task-input" id="taskAnswer" maxlength="100" autocomplete="off" spellcheck="false" value="'+esc(chosen)+'">';
openModal(meta.zh+' · '+g.title,meta.en.toUpperCase()+' · 自由学习',topProgress(s.index,E.sessionQuestions(state,skill).length,check?'无提示复测':s.reviewOnly?'定向巩固':meta.zh)+'<div class="task-layout">'+visual+'<div class="question-content">'+audio+'<h3>'+esc(q.prompt)+'</h3>'+options+'<div class="task-actions"><button class="btn primary" id="submitTask" '+(s.answered?'hidden':'')+'>试试看 '+icon('arrow')+'</button><button class="btn primary" id="nextTask" '+(!s.answered?'hidden':'')+'>'+(s.index===E.sessionQuestions(state,skill).length-1?'完成这个小任务':'下一个小发现')+' '+icon('arrow')+'</button><button id="hintTask" class="hint-btn" '+(s.answered||check?'hidden':'')+'>给我一点提示</button></div><p id="taskFeedback" class="feedback">'+(s.answered?(check?'这次回答已记录。':'这次你找到了！准备好就继续。'):'')+'</p><div id="hintBox" class="hint-box" '+(!s.hint?'hidden':'')+'>'+esc(s.hint?hintText(q,s.hint):'')+'</div></div></div><p id="liveAccuracy" class="activity-note">'+(()=>{const r=E.skillReport(state,skill);return r.answered?'本轮首次答对 '+r.firstCorrect+' / '+r.answered+' · '+r.accuracy+'%':'本轮还没有回答。';})()+'</p><p class="activity-note">练习时可以求助。首次回答和提示会分别记录；完成练习不等于独立掌握。</p>',skill);
if(q.options){$('choices').querySelectorAll('button').forEach(b=>{b.disabled=s.answered;b.onclick=action(async()=>{chosen=q.options[Number(b.dataset.index)];await save(d=>d.skills[skill].draft.response=chosen);$('choices').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});});}else{$('taskAnswer').disabled=s.answered;$('taskAnswer').oninput=()=>{chosen=$('taskAnswer').value;};$('taskAnswer').onchange=()=>{save(d=>d.skills[skill].draft.response=chosen).catch(()=>{});};}
const markAudio=async()=>{if(modalMode!==skill)return;try{await save(d=>{const draft=d.skills[skill].draft;if(draft?.id===s.id&&draft.index===s.index)draft.audioPlayed=true;});}catch{}};
if(skill==='listen'){$('playQuestion').onclick=()=>speak(q.audio,.8,markAudio);$('slowQuestion').onclick=()=>speak(q.audio,.62,markAudio);$('showTranscript').onclick=action(async()=>{await save(d=>{E.hint(d,skill);d.skills[skill].draft.hint=Math.max(2,d.skills[skill].draft.hint);});$('transcript').hidden=false;$('hintBox').hidden=false;$('hintBox').textContent='这是当前题的录音原文。这次使用了文字帮助，会与独立听懂分开记录。';});}if(reading&&!check)$('readAloud').onclick=action(async()=>{await save(d=>{E.hint(d,skill);d.skills[skill].draft.hint=Math.max(2,d.skills[skill].draft.hint);});speak(q.passage||g.readText,.8);toast('本题使用了朗读帮助，已与独立阅读记录分开。');});
$('hintTask').onclick=action(async()=>{const level=await save(d=>E.hint(d,skill));$('hintBox').hidden=false;$('hintBox').textContent='提示 H'+level+'：'+hintText(q,level);renderDashboard();setBuddy('提示只是小扶手。看看线索，再自己试一次。');});
